<script setup>
import {reactive,ref,watch,onBeforeUnmount} from 'vue';
import {action} from '../lib/api.js';
const props=defineProps({work:Object});
const form=reactive({base_url:'',model:'',api_key:''}),visible=ref(false),saving=ref(false),feedback=ref(''),failed=ref(false);
watch(()=>props.work.s.status,status=>{if(status){form.base_url=status.base_url;form.model=status.model;}},{immediate:true});
onBeforeUnmount(()=>form.api_key='');
async function save(){saving.value=true;feedback.value='';failed.value=false;try{const payload={base_url:form.base_url.trim(),model:form.model.trim()};if(form.api_key.trim())payload.api_key=form.api_key.trim();await action('/api/config',payload);form.api_key='';visible.value=false;await props.work.loadStatus();feedback.value='已保存，下一次请求将使用新配置。';props.work.notify('模型配置已保存并生效');}catch(error){feedback.value=error.message;failed.value=true;}finally{saving.value=false;}}
</script>
<template><main id="page-settings" class="page library-page"><div class="library-intro"><div><span class="page-kicker">你的本地工作台</span><h1>连接模型，开始真实任务。</h1><p>在这里管理 API Key、接口地址与模型，保存后立即生效。</p></div></div><section class="settings-panel config-editor"><h2>编辑模型连接</h2><p class="config-description">保存后立即生效。密钥只存储在本机，现有密钥不会回显；留空可保留已保存的密钥。</p><form class="config-form" autocomplete="off" @submit.prevent="save"><div class="config-field"><label for="config-base_url">API 接口地址</label><input id="config-base_url" v-model="form.base_url" type="url" maxlength="2048" required spellcheck="false"><small class="config-help">填写接口基础地址（通常以 /v1 结尾），不要添加 /chat/completions。</small></div><div class="config-field"><label for="config-model">模型名称</label><input id="config-model" v-model="form.model" maxlength="200" required spellcheck="false" placeholder="填写服务商提供的模型 ID"></div><div class="config-field"><label for="config-api_key">API Key</label><div class="secret-field"><input id="config-api_key" v-model="form.api_key" :type="visible?'text':'password'" maxlength="4096" :required="!work.s.status?.configured" autocomplete="new-password" spellcheck="false" :placeholder="work.s.status?.configured?'已配置，留空保持不变':'输入 API Key'" aria-describedby="config-key-help"><button class="secret-toggle" type="button" :aria-label="visible?'隐藏输入的密钥':'显示输入的密钥'" :aria-pressed="visible" @click="visible=!visible">{{visible?'隐藏':'显示'}}</button></div><small id="config-key-help" class="config-help">仅用于当前接口鉴权，不会写入聊天记录或浏览器本地存储。</small></div><div class="config-actions"><span class="config-feedback" :class="{'has-error':failed}" role="status" aria-live="polite">{{feedback}}</span><button type="submit" class="save-config" :disabled="saving||work.s.running">{{saving?'正在保存…':'保存并生效'}}</button></div></form></section><section class="settings-panel"><h2>当前运行配置</h2><div v-for="[label,value] in [['连接状态',work.s.status?.configured?'已配置':'待配置'],['接口地址',work.s.status?.base_url],['模型',work.s.status?.model],['API Key',work.s.status?.configured?'已配置（不回显）':'未配置'],['单次循环上限',`${work.s.status?.max_steps||0} 轮`]]" :key="label" class="settings-row"><span>{{label}}</span><code>{{value}}</code></div></section></main></template>
